from solution import anti_shuffle
import pytest
from hypothesis import given, assume
import hypothesis.strategies as st


def _reference(s: str) -> str:
    # Obviously-correct model: split only on ' ' to preserve blank spaces exactly,
    # sort each word's characters by ascii value, rejoin with single ' '.
    return ' '.join(''.join(sorted(word)) for word in s.split(' '))


# ---- explicit examples from spec ----

def test_example_Hi():
    assert anti_shuffle('Hi') == 'Hi'

def test_example_hello():
    assert anti_shuffle('hello') == 'ehllo'

def test_example_Hello_World():
    assert anti_shuffle('Hello World!!!') == 'Hello !!!Wdlor'


# ---- blank-space preservation (defect in split()/join) ----

def test_empty_string():
    assert anti_shuffle('') == ''

def test_single_space_preserved():
    assert anti_shuffle(' ') == ' '

def test_only_spaces_preserved():
    assert anti_shuffle('   ') == '   '
    assert anti_shuffle('  ') == _reference('  ')

def test_multiple_spaces_between_words():
    assert anti_shuffle('hello  world') == 'ehllo  dlorw'

def test_leading_spaces_preserved():
    assert anti_shuffle('  hello') == '  ehllo'

def test_trailing_spaces_preserved():
    assert anti_shuffle('hello  ') == 'ehllo  '

def test_leading_trailing_and_multiple_spaces():
    s = '  hello   world  '
    assert anti_shuffle(s) == '  ehllo   dlorw  '

def test_consecutive_spaces_word_boundaries():
    # empty words between spaces must stay empty, spaces stay in place
    s = 'a  b   c'
    assert anti_shuffle(s) == _reference(s) == 'a  b   c'


# ---- per-word ascii ordering ----

def test_each_word_sorted_by_ascii():
    assert anti_shuffle('cba') == 'abc'
    assert anti_shuffle('bca acb') == 'abc abc'
    # ascii: 'Z' (90) < 'a' (97), '!' (33) first
    assert anti_shuffle('aZ!') == '!Za'
    assert anti_shuffle('World!!!') == '!!!Wdlor'

def test_word_order_preserved():
    assert anti_shuffle('dc ba') == 'cd ab'
    # first word sorts to second position alphabetically but must stay first
    s = 'zyx abc'
    assert anti_shuffle(s) == 'xyz abc'

def test_spaces_positions_unchanged():
    s = 'ab cd  ef '
    r = anti_shuffle(s)
    assert len(r) == len(s)
    for i, ch in enumerate(s):
        assert (ch == ' ') == (r[i] == ' ')


# ---- property-based tests ----

@given(st.text(alphabet=st.sampled_from(['a', 'b', 'c', 'Z', 'z', '0', '!', ' ']), max_size=20))
def test_property_equivalence_to_reference(s):
    assert anti_shuffle(s) == _reference(s)

@given(st.text(alphabet=st.sampled_from(['a', 'H', 'l', 'o', 'W', 'r', 'd', '!', ' ']), max_size=30))
def test_property_length_preserved(s):
    assert len(anti_shuffle(s)) == len(s)

@given(st.text(alphabet=st.sampled_from(['a', 'b', 'X', 'y', ' ', ' ', ' ']), max_size=25))
def test_property_space_positions_preserved(s):
    r = anti_shuffle(s)
    assert len(r) == len(s)
    for orig_c, res_c in zip(s, r):
        assert (orig_c == ' ') == (res_c == ' ')

@given(st.text(alphabet=st.sampled_from(['a', 'b', 'c', 'A', 'B', '!', '0', ' ']), max_size=25))
def test_property_each_space_separated_word_sorted(s):
    r = anti_shuffle(s)
    orig_words = s.split(' ')
    res_words = r.split(' ')
    assert len(orig_words) == len(res_words)
    for ow, rw in zip(orig_words, res_words):
        assert list(rw) == sorted(ow)
        assert [ord(c) for c in rw] == sorted(ord(c) for c in ow)

@given(st.text(alphabet=st.sampled_from(['a', 'b', 'Z', '!', ' ']), max_size=25))
def test_property_global_nonspace_multiset_preserved(s):
    r = anti_shuffle(s)
    assert sorted(c for c in s if c != ' ') == sorted(c for c in r if c != ' ')
    assert s.count(' ') == r.count(' ')

@given(st.text(alphabet=st.sampled_from(['a', 'b', 'c', ' ', ' ']), max_size=20))
def test_property_idempotent(s):
    once = anti_shuffle(s)
    assert anti_shuffle(once) == once

@given(st.integers(min_value=0, max_value=10))
def test_property_only_spaces_identity(n):
    s = ' ' * n
    assert anti_shuffle(s) == s
